export const BODY: string = "\n<p>مئتا كيلوبايت هي النقطة التي يتوقف عندها ضغط الصور عن كونه حلًا وسطًا، ويبدأ في أن يكون جودة حقيقية. الصورة بهذا الحجم تبدو ممتازة على الشاشة.</p>\n<p>المدونات والمتاجر الإلكترونية ومنصات المحتوى تستخدم 200 كيلوبايت معيارًا لصورها. إنه الحجم الذي يوازن بين الجودة وسرعة التحميل.</p>\n<p>يشرح هذا الدليل كيف تضغط صورة إلى 200 كيلوبايت، ومتى يكون هذا الحجم مناسبًا، وكيف تحافظ على الجودة أثناء ذلك.</p>\n<h2 id=\"why-200kb\">لماذا 200 كيلوبايت هو المعيار لصور الويب؟</h2>\n<p>200 كيلوبايت هو معيار صور الويب لأنه يشتري جودة حقيقية بسعر معقول. الصورة بهذا الحجم تبدو واضحة على الشاشات العادية، وملفها خفيف بما يكفي للتحميل السريع.</p>\n<p>معظم أنظمة إدارة المحتوى والمتاجر تتعامل مع هذا الحجم بسهولة. لذلك أصبح الحجم الافتراضي الذي يوصي به مطورو المواقع.</p>\n<h2 id=\"how-the-tool-works\">كيف يعمل ضاغط 200 كيلوبايت؟</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> في متصفحك. كل المعالجة تتم على جهازك، فلا تُرفع صورتك إلى أي خادم.</p>\n<p>تبحث الأداة تلقائيًا عن أعلى جودة تناسب 200 كيلوبايت. النتيجة هي أوضح نسخة ممكنة من صورتك عند هذا الحجم.</p>\n<h2 id=\"quality-at-200kb\">كيف تبدو الجودة عند 200 كيلوبايت؟</h2>\n<p>الجودة عند 200 كيلوبايت ممتازة. على الشاشات العادية يصعب تمييز الصورة المضغوطة عن الأصل، حتى عند النظر عن قرب.</p>\n<p>الفرق يظهر فقط في التفاصيل الدقيقة جدًا أو عند التكبير الشديد. لصور الويب العادية، لا يهم هذا الفرق إطلاقًا.</p>\n<h2 id=\"ecommerce-photos\">200 كيلوبايت للتجارة الإلكترونية وصور المنتجات</h2>\n<p>صور المنتجات تناسب 200 كيلوبايت تمامًا. المشتري يرى تفاصيل المنتج بوضوح، والصفحة تحمل بسرعة دون انتظار طويل.</p>\n<p>لصور المنتجات، قصّ الصورة على المنتج نفسه قبل الضغط. القص المحكم يمنح المنتج حصة أكبر من الميزانية فيبدو أوضح.</p>\n<h2 id=\"blogs-and-cms\">200 كيلوبايت للمدونات ومواقع المحتوى</h2>\n<p>المدونات تستخدم 200 كيلوبايت للصور الرئيسية والمميزة. الصورة الكبيرة في أعلى المقال تستحق حجمًا أكبر لأنها أول ما يراه القارئ.</p>\n<p>للصور الصغيرة داخل المقال، يكفي 100 كيلوبايت. ولتحسين صور موقعك كاملًا، استخدم <a href=\"/ar/tahsin-suwar-al-web/\">محسّن صور الويب</a> مع إعداداته الجاهزة.</p>\n<h2 id=\"formats-at-200kb\">JPG مقابل PNG مقابل WebP عند 200 كيلوبايت</h2>\n<p>عند 200 كيلوبايت، JPG هو الخيار الآمن للصور الفوتوغرافية. يعطي جودة ممتازة ويعمل في كل مكان دون مشاكل توافق.</p>\n<p>WebP أصغر قليلًا بجودة مماثلة، لكن تأكد من قبول منصتك له. أما PNG فيناسب الرسوم والنصوص فقط، لا الصور الفوتوغرافية.</p>\n<h2 id=\"dimension-scaling\">تقليص الأبعاد عند 200 كيلوبايت</h2>\n<p>إذا لم تصل الجودة وحدها إلى 200 كيلوبايت، تقلّص الأداة الأبعاد تدريجيًا. التقليص البطيء يحافظ على أكبر قدر ممكن من التفاصيل.</p>\n<p>يمكنك أيضًا قص الصورة قبل الضغط. إزالة المساحات الفارغة تمنح الموضوع الرئيسي حصة أكبر من الميزانية.</p>\n<h2 id=\"batch-200kb\">الضغط الجماعي إلى 200 كيلوبايت</h2>\n<p>لضغط صور كثيرة إلى 200 كيلوبايت، استخدم أداة الضغط الجماعي. ارفع الدفعة كاملة وحدد الهدف مرة واحدة، ثم نزّل كل شيء كملف ZIP.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"heic-and-raw\">صور HEIC والملفات الكبيرة من الكاميرا</h2>\n<p>صور HEIC من آيفون والملفات الخام من الكاميرات كبيرة جدًا، لكنها تضغط إلى 200 كيلوبايت بسهولة لأنها تحمل تفاصيل كثيرة.</p>\n<p>حوّل HEIC إلى JPG أولًا إذا كانت منصتك لا تقبله. التحويل من الملف الأصلي يحافظ على الجودة أفضل من التحويل من نسخة مضغوطة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند 200 كيلوبايت</h2>\n<p>أكثر الأخطاء شيوعًا البدء من نسخة مضغوطة أصلًا. كل جولة ضغط تضيف ضررًا، فابدأ دائمًا من الملف الأصلي بأعلى جودة.</p>\n<p>خطأ آخر أن تثبّت الصيغة على PNG لصورة فوتوغرافية. PNG لا يضغط الصور بكفاءة، وقد يفشل في الوصول إلى 200 كيلوبايت مع الصور المفصلة.</p>\n<h2 id=\"when-200kb-is-wrong\">متى يكون 200 كيلوبايت الحجم الخاطئ؟</h2>\n<p>200 كيلوبايت ليس مناسبًا دائمًا. للنماذج الصارمة التي تطلب 50 أو 100 كيلوبايت، سيُرفض الملف مهما كانت جودته.</p>\n<p>في هذه الحالة استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-50kb/\">ضاغط 50 كيلوبايت</a>. اختر الحجم الذي تطلبه البوابة لا الذي تفضله.</p>\n<h2 id=\"colour-accuracy\">دقة الألوان عند 200 كيلوبايت</h2>\n<p>دقة الألوان عند 200 كيلوبايت ممتازة لمعظم الاستخدامات. التدرجات ناعمة والشرائط اللونية نادرة بهذا الحجم.</p>\n<p>لصور المنتجات حيث يهم اللون الدقيق، راجع النتيجة على شاشة جيدة. إذا بدا اللون صحيحًا هناك، فهو صحيح لمعظم المشاهدين.</p>\n<h2 id=\"cropping-for-shops\">كيف تقص صور المنتجات قبل الضغط؟</h2>\n<p>قصّ صور المنتجات قبل الضغط يحدث فرقًا كبيرًا. أزل المساحات الفارغة حول المنتج، واجعل المنتج يملأ معظم الإطار.</p>\n<p>القص المحكم يمنح المنتج حصة أكبر من ميزانية 200 كيلوبايت، فتظهر التفاصيل أوضح ويبدو المتجر أكثر احترافية.</p>\n<h2 id=\"seo-images\">تحسين محركات البحث للصور عند 200 كيلوبايت</h2>\n<p>تحسين محركات البحث للصور يبدأ من اسم الملف والنص البديل. سمِّ ملفك بكلمات تصف المنتج أو الموضوع، واكتب نصًا بديلًا واضحًا.</p>\n<p>حجم 200 كيلوبايت يساعد أيضًا في سرعة الصفحة، وسرعة الصفحة عامل ترتيب مهم في محركات البحث. الصور السريعة ترفع ترتيب موقعك.</p>\n<h2 id=\"archiving-200kb\">الأرشفة: 200 كيلوبايت ليس حجم ملف أرشيف</h2>\n<p>200 كيلوبايت ليس حجم أرشيف. للأرشفة، احتفظ بالملف الأصلي بأعلى جودة، واستخدم نسخ 200 كيلوبايت للنشر على الويب فقط.</p>\n<p>الملف المضغوط لا يمكن إعادته إلى جودة الأصل. لذلك افصل بين مجلد الأرشيف ومجلد النشر، ولا تحذف الأصل أبدًا.</p>\n<h2 id=\"measuring-success\">كيف تقيس النجاح بعد الضغط؟</h2>\n<p>قس نجاحك بسرعة تحميل الصفحة قبل الضغط وبعده. أدوات قياس السرعة المجانية تظهر الفرق بوضوح، وعادة يتحسن الوقت بشكل ملحوظ.</p>\n<p>تابع أيضًا معدل ارتداد الزوار. وللخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-daght-as-sura-ila-200kb/\">كيفية ضغط صورة إلى 200 كيلوبايت</a> ودليل <a href=\"/ar/blog/suwar-200kb-li-bawabat-al-tawzif-wa-al-namadhij/\">صور 200 كيلوبايت لبوابات التوظيف والنماذج</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a> لأحجام مخصصة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل 200 كيلوبايت جودة جيدة لصورة موقع إلكتروني؟","answer":"نعم، 200 كيلوبايت جودة ممتازة لصور المواقع. تبدو معظم الصور مطابقة للأصل تقريبًا بأحجام العرض العادية، وهو المعيار الذي تستخدمه المدونات والمتاجر."},{"question":"هل يمكن لصورة كاميرا 24 ميغابكسل أن تصل إلى 200 كيلوبايت بشكل نظيف؟","answer":"نعم، إذا بدأت من الملف الأصلي. صورة كاميرا 24 ميغابكسل تزن عشرات الميغابايت، لكن الضغط الذكي إلى 200 كيلوبايت يحافظ على تفاصيل كافية للعرض على الشاشة."},{"question":"هل أستخدم JPG أم WebP عند 200 كيلوبايت؟","answer":"للصور الفوتوغرافية، JPG هو الخيار الآمن ويعمل في كل مكان. WebP أصغر قليلًا بجودة مماثلة، لكن تأكد من قبول موقعك ومنصتك له قبل الاعتماد عليه."},{"question":"هل يزيل الضغط إلى 200 كيلوبايت البيانات الوصفية لصورتي؟","answer":"نعم، تزيل الأداة بيانات EXIF ووسوم موقع GPS أثناء الضغط. الملف المنزّل لا يحمل موقع التقاط الصورة، وهذا يحمي خصوصيتك عند نشر الصور على موقعك."},{"question":"ماذا لو كانت صورتي أقل من 200 كيلوبايت أصلًا؟","answer":"لا بأس. إذا كانت صورتك أقل من 200 كيلوبايت أصلًا وتبدو جيدة، فاستخدمها كما هي. مرّرها عبر الأداة فقط إذا أردت توحيد الصيغة أو إزالة البيانات الوصفية."},{"question":"هل يمكنني ضغط PNG شفاف إلى 200 كيلوبايت دون فقدان الشفافية؟","answer":"نعم، باستخدام WebP أو PNG. PNG يحفظ الشفافية دون فقدان لكنه أكبر حجمًا، بينما WebP يحفظ الشفافية بحجم أصغر. JPG لا يدعم الشفافية أبدًا."}];
